-- 두 건이면 터진다

@Test
@Transactional
void 두_건() {
    em.persist(new Member("같은이름", 10));
    em.persist(new Member("같은이름", 20));
    em.flush(); em.clear();

    try {
        memberRepository.findMemberByUsername("같은이름");
    } catch (Exception e) {
        System.out.println("Member  : " + e.getClass().getSimpleName());
    }
    em.clear();
    try {
        memberRepository.findOptionalByUsername("같은이름");
    } catch (Exception e) {
        System.out.println("Optional: " + e.getClass().getSimpleName());
    }
}

