-- Stream 은 닫아야 한다

@Query("select m from Member m")
Stream<Member> streamAll();

@Test
@Transactional
void 스트림() {
    em.clear();
    try (Stream<Member> s = memberRepository.streamAll()) {
        long n = s.filter(m -> m.getAge() > 15).count();
        System.out.println("15살 초과: " + n);
    }
}

